import { useEffect, useMemo, useState } from "react";
import { skipToken } from "@tanstack/react-query";
import { Accessibility, ArrowDownRight, ArrowRight, Bell, Check, CheckCircle2, ClipboardList, Download, ExternalLink, FileText, HeartHandshake, Languages, LockKeyhole, MapPinned, MessageSquareWarning, MoreHorizontal, Navigation, PhoneCall, RefreshCw, Send, ShieldAlert, SlidersHorizontal, Sparkles, TriangleAlert, Type, UserRound, UsersRound, Volume2, Wifi, WifiOff } from "lucide-react";
import { toast } from "sonner";
import { Link } from "wouter";
import { trpc } from "@/lib/trpc";
import { Card, DemoLabel, PageHeader, ProgressBar, SectionTitle, SignalBridgeShell, SignalMap, StatusPill } from "@/components/SignalBridgeShell";

const formatTime = (date: Date | string | null | undefined) => date ? new Date(date).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" }) : "—";
const formatDate = (date: Date | string | null | undefined) => date ? new Date(date).toLocaleDateString([], { day: "2-digit", month: "short", year: "numeric" }) : "—";
const severityTone = (severity?: string) => severity === "critical" || severity === "high" || severity === "warning" ? "red" : severity === "moderate" || severity === "watch" ? "amber" : severity === "advisory" ? "cyan" : "green";
const priorityTone = (priority?: string) => priority === "now" ? "red" : priority === "next" ? "amber" : "green";

function Workspace({ children }: { children: React.ReactNode }) { return <SignalBridgeShell><div className="mx-auto max-w-[1480px] px-5 py-7 md:px-8 md:py-9">{children}</div></SignalBridgeShell>; }
function LoadingCard() { return <Card className="p-6"><div className="h-4 w-32 animate-pulse rounded bg-[#e7eef1]" /><div className="mt-4 h-8 w-3/4 animate-pulse rounded bg-[#e7eef1]" /><div className="mt-3 h-3 w-full animate-pulse rounded bg-[#eef3f5]" /></Card>; }
function NextPhaseNotice({ text = "Live official feeds, responder handoff, verified emergency contacts and human review remain explicit integration boundaries." }: { text?: string }) { return <div className="flex gap-3 rounded-xl border border-dashed border-[#b9ccd3] bg-[#f8fbfc] p-4 text-sm text-[#5c6d79]"><Sparkles size={17} className="mt-0.5 shrink-0 text-[#2e8b91]" /><div><div className="font-semibold text-[#27445b]">Coming in next integration phase</div><div className="mt-1 leading-5">{text}</div></div></div>; }

export function DashboardPage() {
  const { data, isLoading, refetch } = trpc.signalbridge.snapshot.useQuery();
  const { data: safeLoop } = trpc.signalbridge.safeLoop.useQuery();
  if (isLoading || !data) return <Workspace><PageHeader eyebrow="COMMAND / OVERVIEW" title="Emergency dashboard" description="Loading the latest SignalBridge snapshot." /><div className="mt-7 grid gap-5 md:grid-cols-2"><LoadingCard /><LoadingCard /></div></Workspace>;
  const activeWarning = data.warnings.find(w => w.status === "active") ?? data.warnings[0];
  const completed = data.actionPlans.filter(plan => plan.status === "complete").length;
  const checkedIn = safeLoop?.currentStatus === "SAFE";
  const corroboratedReports = data.citizenReports.filter(report => report.verificationStatus === "corroborated" || report.verificationStatus === "triaged").length;
  return <Workspace>
    <PageHeader eyebrow="COMMAND / OVERVIEW" title="Emergency dashboard" description="A structured view of what is happening, what is trusted, and what to do next in the Chennai flood demonstration environment." action={<div className="flex items-center gap-2"><DemoLabel /><button onClick={() => refetch()} className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] transition hover:border-[#7fb8bf]"><RefreshCw size={14} /> Refresh</button></div>} />
    <div className="mt-7 flex flex-wrap items-center gap-3 rounded-xl border border-[#e7d19d] bg-[#fff8e8] px-4 py-3 text-sm text-[#6f5019]"><TriangleAlert size={17} className="text-[#d39124]" /><span className="font-semibold">Active emergency status:</span><span>{activeWarning.title}</span><span className="ml-auto font-mono text-[10px] uppercase tracking-[.12em]">Valid until {formatTime(activeWarning.validUntil)} IST</span></div>
    <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Localized risk" value="HIGH" detail="Perambur / North Chennai" tone="red" icon={<ShieldAlert size={18} />} /><Metric label="Active warnings" value={String(data.warnings.length).padStart(2, "0")} detail="2 sources · all current" tone="cyan" icon={<RadioIcon />} /><Metric label="Action readiness" value={`${completed}/${data.actionPlans.length}`} detail="Steps prepared for you" tone="green" icon={<ClipboardList size={18} />} /><Metric label="Community pulse" value={`${corroboratedReports}/${data.citizenReports.length}`} detail="Reports triaged or corroborated" tone="amber" icon={<UsersRound size={18} />} /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
      <div className="space-y-5"><Card className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-4 border-b border-[#e4ebee] p-5 md:p-6"><div><div className="flex items-center gap-2"><StatusPill tone={severityTone(activeWarning.severity)}>{activeWarning.severity}</StatusPill><span className="font-mono text-[10px] uppercase tracking-[.11em] text-[#84949d]">Issued {formatTime(activeWarning.issuedAt)} IST</span></div><h2 className="mt-3 max-w-[560px] font-display text-2xl font-semibold tracking-[-.035em] text-[#0d1b2a]">{activeWarning.title}</h2><p className="mt-2 max-w-[620px] text-sm leading-6 text-[#5c6d79]">{activeWarning.summary}</p></div><Link href="/alerts" className="sb-focus inline-flex items-center gap-1.5 rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]">Review alerts <ArrowRight size={14} /></Link></div><div className="grid gap-3 p-5 md:grid-cols-3 md:p-6"><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Affected area</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{activeWarning.area}</div></div><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Warning source</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{activeWarning.sourceLabel}</div></div><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Trust state</div><div className="mt-2 flex items-center gap-1.5 text-sm font-semibold text-[#2e8b70]"><CheckCircle2 size={15} /> Official + corroborated</div></div></div></Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="ACTIONFORGE / CURRENT PLAN" title="Your next safe actions" action={<Link href="/action-plans" className="sb-focus text-xs font-semibold text-[#2e8b91] hover:underline">Open full plan →</Link>} /><div className="space-y-3">{data.actionPlans.slice(0, 3).map((plan, index) => <div key={plan.id} className="flex gap-3 rounded-lg border border-[#e4ebee] p-3"><div className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-xs font-bold ${plan.status === "complete" ? "bg-[#daf0e8] text-[#21684f]" : plan.status === "in_progress" ? "bg-[#fff2d4] text-[#7d5411]" : "bg-[#e8eef4] text-[#27445b]"}`}>{plan.status === "complete" ? <Check size={15} /> : index + 1}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="font-semibold text-[#27445b]">{plan.title}</span><StatusPill tone={priorityTone(plan.priority)}>{plan.priority === "now" ? "Now" : plan.priority === "next" ? "Next" : "Ready"}</StatusPill></div><div className="mt-1 text-xs leading-5 text-[#71818b]">{plan.description}</div></div></div>)}</div></Card></div>
      <div className="space-y-5"><Card className="overflow-hidden"><div className="flex items-center justify-between p-5 pb-3 md:p-6 md:pb-3"><SectionTitle eyebrow="GEOSHIELD / LOCAL VIEW" title="Risk around you" /><Link href="/risk-map" className="sb-focus text-xs font-semibold text-[#2e8b91] hover:underline">Open map →</Link></div><div className="px-5 pb-5 md:px-6 md:pb-6"><SignalMap compact /></div><div className="flex items-center gap-4 border-t border-[#e4ebee] px-5 py-3 text-[10px] font-mono uppercase tracking-[.1em] text-[#84949d] md:px-6"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#c75252]" /> Severe</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#dd9c30]" /> Moderate</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#2e8b70]" /> Lower</span></div></Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="SAFELOOP / CHECK-IN" title="Safety status" action={<StatusPill tone={checkedIn ? "green" : safeLoop?.currentStatus === "ASSISTANCE NEEDED" ? "red" : "amber"}>{safeLoop?.currentStatus ?? "Loading"}</StatusPill>} /><p className="text-sm leading-6 text-[#5c6d79]">{checkedIn ? "Your status is current for this monitoring window. We will keep monitoring for changes in your area." : safeLoop?.currentStatus === "ASSISTANCE NEEDED" ? "Assistance needed is recorded for this prototype; no responder is automatically dispatched." : "Choose a response state after reviewing your ActionForge plan."}</p><div className="mt-4 flex flex-wrap gap-2"><Link href="/safety" className="sb-focus inline-flex items-center gap-2 rounded-lg bg-[#0d3448] px-3.5 py-2.5 text-xs font-semibold text-white hover:bg-[#174a60]"><CheckCircle2 size={15} /> Update safety status</Link><Link href="/safety" className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3.5 py-2.5 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]">View timeline</Link></div></Card></div>
    </div>
    <div className="mt-5"><NextPhaseNotice /></div>
  </Workspace>;
}

function Metric({ label, value, detail, tone, icon }: { label: string; value: string; detail: string; tone: "red" | "cyan" | "green" | "amber"; icon: React.ReactNode }) { const palette = { red: "text-[#b64242] bg-[#fde5e3]", cyan: "text-[#0d5960] bg-[#d9f1f0]", green: "text-[#21684f] bg-[#daf0e8]", amber: "text-[#7d5411] bg-[#fff2d4]" }; return <Card className="p-4"><div className="flex items-start justify-between"><div className="font-mono text-[9px] uppercase tracking-[.15em] text-[#84949d]">{label}</div><div className={`rounded-lg p-2 ${palette[tone]}`}>{icon}</div></div><div className="mt-5 font-display text-3xl font-semibold tracking-[-.04em] text-[#0d1b2a]">{value}</div><div className="mt-1 text-xs text-[#71818b]">{detail}</div></Card>; }
function RadioIcon() { return <div className="relative h-[18px] w-[18px]"><span className="absolute left-[6px] top-[6px] h-2 w-2 rounded-full bg-current" /><span className="absolute left-[3px] top-[3px] h-3.5 w-3.5 rounded-full border border-current opacity-60" /><span className="absolute left-0 top-0 h-[18px] w-[18px] rounded-full border border-current opacity-30" /></div>; }

export function AlertsPage() {
  const { data: warnings, isLoading } = trpc.signalbridge.warnings.useQuery();
  const { data: rawAlert } = trpc.signalbridge.rawDemoAlert.useQuery();
  const { data: defaultIntelligence } = trpc.signalbridge.alertIntelligence.useQuery();
  const interpret = trpc.signalbridge.interpretAlert.useMutation();
  const [draft, setDraft] = useState<Record<string, string> | null>(null);
  const [interpreted, setInterpreted] = useState<typeof defaultIntelligence>();
  const current = draft ?? (rawAlert ? { ...rawAlert } : null);
  const updateDraft = (field: string, value: string) => setDraft({ ...(current ?? {}), [field]: value });
  const runInterpretation = () => {
    if (!current) return;
    interpret.mutate(current as Parameters<typeof interpret.mutate>[0], { onSuccess: setInterpreted });
  };
  const intelligence = interpreted ?? defaultIntelligence;
  return <Workspace>
    <PageHeader eyebrow="SIGNALCORE / ALERT INTELLIGENCE" title="Alert intelligence" description="Convert a raw warning into structured emergency intelligence while keeping source provenance and demo boundaries visible." action={<div className="flex items-center gap-2"><DemoLabel /><StatusPill tone="cyan">Interpretation ready</StatusPill></div>} />
    <div className="mt-7 grid gap-5 xl:grid-cols-[.82fr_1.18fr]">
      <Card className="p-5 md:p-6">
        <SectionTitle eyebrow="RAW WARNING INGESTION" title="Alert ingestion interface" action={<span className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">SignalCore input</span>} />
        <p className="mb-5 text-xs leading-5 text-[#71818b]">This form uses a realistic Chennai flood warning. No live official feed is connected in this phase.</p>
        <div className="space-y-3">
          <AlertField label="Alert ID" value={current?.alertId} onChange={value => updateDraft("alertId", value)} />
          <div className="grid gap-3 sm:grid-cols-2"><AlertField label="Hazard type" value={current?.hazardType} onChange={value => updateDraft("hazardType", value)} /><label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Severity</span><select value={current?.severity ?? "warning"} onChange={event => updateDraft("severity", event.target.value)} className="sb-focus mt-1.5 w-full rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm text-[#27445b]"><option value="advisory">Advisory</option><option value="watch">Watch</option><option value="warning">Warning</option><option value="critical">Critical</option></select></label></div>
          <AlertField label="Source" value={current?.source} onChange={value => updateDraft("source", value)} /><div className="grid gap-3 sm:grid-cols-2"><AlertField label="Affected area" value={current?.affectedArea} onChange={value => updateDraft("affectedArea", value)} /><label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Source status</span><select value={current?.sourceStatus ?? "simulated"} onChange={event => updateDraft("sourceStatus", event.target.value)} className="sb-focus mt-1.5 w-full rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm text-[#27445b]"><option value="simulated">Simulated</option><option value="official">Official</option><option value="connected">Connected</option></select></label></div>
          <div className="grid gap-3 sm:grid-cols-3"><AlertField label="Issue time" value={current?.issueTime} onChange={value => updateDraft("issueTime", value)} /><AlertField label="Valid from" value={current?.validFrom} onChange={value => updateDraft("validFrom", value)} /><AlertField label="Expiry time" value={current?.expiryTime} onChange={value => updateDraft("expiryTime", value)} /></div>
          <label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Warning text</span><textarea value={current?.warningText ?? ""} onChange={event => updateDraft("warningText", event.target.value)} className="sb-focus mt-1.5 min-h-[72px] w-full resize-y rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm leading-5 text-[#27445b]" /></label>
          <label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Recommended official precautions</span><textarea value={current?.recommendedPrecautions ?? ""} onChange={event => updateDraft("recommendedPrecautions", event.target.value)} className="sb-focus mt-1.5 min-h-[82px] w-full resize-y rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm leading-5 text-[#27445b]" /></label>
          <button onClick={runInterpretation} disabled={!current || interpret.isPending} className="sb-focus inline-flex w-full items-center justify-center gap-2 rounded-lg bg-[#0d3448] px-4 py-3 text-sm font-semibold text-white transition hover:bg-[#174a60] disabled:cursor-not-allowed disabled:opacity-60"><Sparkles size={16} /> {interpret.isPending ? "Interpreting…" : "Run SignalCore interpretation"}</button>
        </div>
      </Card>
      <div className="space-y-5">
        <Card className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-3 border-b border-[#e4ebee] p-5 md:p-6"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#2e8b91]">STRUCTURED ALERT OBJECT</div><h2 className="mt-2 font-display text-2xl font-semibold tracking-[-.035em] text-[#0d1b2a]">Alert Intelligence</h2></div><DemoLabel>{intelligence?.intelligenceStatus ?? "Demo interpretation"}</DemoLabel></div>{intelligence && <div className="grid gap-4 p-5 md:grid-cols-2 md:p-6"><StructuredField label="Hazard" value={intelligence.hazard} /><StructuredField label="Severity" value={intelligence.severity.toUpperCase()} tone={severityTone(intelligence.severity)} /><StructuredField label="Affected zones" value={intelligence.affectedZones.join(" · ")} /><StructuredField label="Time window" value={`${formatTime(intelligence.timeWindow.validFrom)} → ${formatTime(intelligence.timeWindow.expiryTime)} IST`} /><StructuredField label="Source" value={intelligence.source} /><StructuredField label="Source status" value={intelligence.sourceStatus.toUpperCase()} tone={intelligence.sourceStatus === "simulated" ? "amber" : "green"} /><StructuredField label="Confidence" value={`${intelligence.confidence}%`} tone={intelligence.confidence > 85 ? "green" : "amber"} /><StructuredField label="Processed" value={formatTime(intelligence.timestamp)} /><div className="md:col-span-2 rounded-lg bg-[#f4f7f9] p-4"><div className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">Extracted guidance</div><div className="mt-3 space-y-2">{intelligence.extractedInstructions.map((instruction, index) => <div key={`${instruction}-${index}`} className="flex gap-2 text-sm leading-5 text-[#27445b]"><span className="font-mono text-[10px] text-[#2e8b91]">0{index + 1}</span><span>{instruction}</span></div>)}</div></div></div>}</Card>
        <NextPhaseNotice text="This MVP uses deterministic extraction and clearly labels the result as demo intelligence. Live source ingestion, model-backed interpretation and human review are coming in next integration phase." />
      </div>
    </div>
    <div className="mt-6"><SectionTitle eyebrow="ALERT INTELLIGENCE REGISTER" title="Structured alerts" action={<span className="font-mono text-[10px] uppercase tracking-[.11em] text-[#84949d]">{warnings?.length ?? 0} records</span>} />{isLoading ? <LoadingCard /> : <Card className="overflow-hidden"><div className="hidden overflow-x-auto md:block"><table className="w-full min-w-[900px] text-left"><thead className="bg-[#f4f7f9] font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]"><tr><th className="px-5 py-3">Source</th><th className="px-5 py-3">Hazard</th><th className="px-5 py-3">Severity</th><th className="px-5 py-3">Affected area</th><th className="px-5 py-3">Validity</th><th className="px-5 py-3">Official status</th><th className="px-5 py-3">Extracted guidance</th></tr></thead><tbody className="divide-y divide-[#e4ebee]">{warnings?.map(warning => <tr key={warning.id} className="align-top"><td className="px-5 py-4"><div className="font-semibold text-[#27445b]">{warning.sourceLabel}</div><div className="mt-1 font-mono text-[10px] text-[#84949d]">{warning.alertId}</div></td><td className="px-5 py-4 text-sm text-[#27445b]">{warning.hazardType}</td><td className="px-5 py-4"><StatusPill tone={severityTone(warning.severity)}>{warning.severity}</StatusPill></td><td className="px-5 py-4 text-sm leading-5 text-[#5c6d79]">{warning.area}</td><td className="px-5 py-4 whitespace-nowrap font-mono text-[10px] text-[#71818b]">{formatTime(warning.validFrom)}–{formatTime(warning.validUntil)} IST</td><td className="px-5 py-4"><StatusPill tone={warning.sourceStatus === "simulated" ? "amber" : "green"}>{warning.sourceStatus === "simulated" ? "Demo" : warning.sourceStatus}</StatusPill></td><td className="max-w-[260px] px-5 py-4 text-sm leading-5 text-[#5c6d79]">{warning.recommendedPrecautions}</td></tr>)}</tbody></table></div><div className="space-y-3 p-4 md:hidden">{warnings?.map(warning => <div key={warning.id} className="rounded-lg border border-[#e4ebee] p-4"><div className="flex items-center justify-between gap-2"><StatusPill tone={severityTone(warning.severity)}>{warning.severity}</StatusPill><StatusPill tone={warning.sourceStatus === "simulated" ? "amber" : "green"}>{warning.sourceStatus}</StatusPill></div><div className="mt-3 font-semibold text-[#27445b]">{warning.title}</div><div className="mt-1 text-xs text-[#84949d]">{warning.sourceLabel} · {warning.area}</div><div className="mt-3 text-sm leading-5 text-[#5c6d79]">{warning.recommendedPrecautions}</div></div>)}</div></Card>}</div>
    {warnings?.map(warning => <div key={`provenance-${warning.id}`} className="mt-4"><ProvenancePanel warning={warning} /></div>)}
  </Workspace>;
}
function SourceRow({ name, type, status }: { name: string; type: string; status: string }) { return <div className="flex items-start gap-3"><span className="mt-1 h-2 w-2 rounded-full bg-[#2e8b70]" /><div className="min-w-0 flex-1"><div className="text-sm font-semibold text-[#27445b]">{name}</div><div className="mt-0.5 text-xs text-[#84949d]">{type}</div></div><span className="font-mono text-[10px] uppercase tracking-[.1em] text-[#2e8b70]">{status}</span></div>; }

export function RiskMapPage() {
  const [selectedPoint, setSelectedPoint] = useState({ lat: 13.111, lng: 80.244 });
  const [locationQuery, setLocationQuery] = useState("Perambur, Chennai");
  const [routeResult, setRouteResult] = useState<{ status: string; distanceKm: number | null; durationMinutes: number | null; source: string; message?: string } | null>(null);
  const { data: assessment, isFetching } = trpc.signalbridge.riskAssessment.useQuery(selectedPoint);
  const { data: integrations } = trpc.signalbridge.integrationStatus.useQuery();
  const geocode = trpc.signalbridge.geocode.useMutation();
  const route = trpc.signalbridge.routeDistance.useMutation();
  const shelterInput = useMemo(() => assessment ? { name: assessment.nearestShelter.name, capacity: 0, availableSpaces: 0, status: assessment.nearestShelter.status } : undefined, [assessment]);
  const { data: shelter } = trpc.signalbridge.shelterAvailability.useQuery(shelterInput ?? skipToken);
  const findLocation = () => geocode.mutate({ query: locationQuery }, { onSuccess: result => { if (result.result) { setSelectedPoint({ lat: result.result.lat, lng: result.result.lng }); toast.success("Location found", { description: result.result.label }); } else toast.info("Location not found", { description: result.message ?? "Try a nearby landmark or Chennai area." }); } });
  const calculateRoute = () => { if (!assessment) return; route.mutate({ from: selectedPoint, to: assessment.nearestShelter.point }, { onSuccess: setRouteResult }); };
  return <Workspace>
    <PageHeader eyebrow="GEOSHIELD / RISK & RELEVANCE" title="Risk map" description="Select a location to determine whether it intersects a simulated warning polygon, then review live geocoding, shelter status, and route distance where configured." action={<div className="flex items-center gap-2"><DemoLabel>Simulated boundaries</DemoLabel><button onClick={() => setSelectedPoint({ lat: 13.111, lng: 80.244 })} className="sb-focus rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]">Use demo location</button></div>} />
    <div className="mt-7 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card className="overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e4ebee] px-5 py-4 md:px-6"><div><div className="flex items-center gap-2 text-sm font-semibold text-[#27445b]"><MapPinned size={16} className="text-[#2e8b91]" /> Chennai metropolitan area</div><div className="mt-1 text-xs text-[#84949d]">Click the map to calculate location relevance · {isFetching ? "assessing…" : "assessment current"}</div></div><StatusPill tone={assessment?.state === "ACTION" ? "red" : assessment?.state === "WATCH" ? "amber" : "green"}>{assessment?.state ?? "Loading"}</StatusPill></div><SignalMap selectedPoint={selectedPoint} onSelectPoint={setSelectedPoint} /><div className="grid gap-3 border-t border-[#e4ebee] bg-[#f8fbfc] p-4 sm:grid-cols-2 lg:grid-cols-4"><MapLegend color="#c75252" label="ACTION" detail="Inside flood polygon" /><MapLegend color="#dd9c30" label="WATCH" detail="Inside watch polygon" /><MapLegend color="#2e8b70" label="SAFE" detail="Outside polygons" /><MapLegend color="#2e8b91" label="ROUTE" detail="Reference road" /></div></Card>
      <div className="space-y-5"><Card className="p-5 md:p-6"><div className="flex items-start justify-between gap-3"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#2e8b91]">SELECTED LOCATION</div><h2 className="mt-2 font-display text-2xl font-semibold text-[#0d1b2a]">{assessment?.state ?? "Assessing…"}</h2></div><div className={`rounded-xl p-3 ${assessment?.state === "ACTION" ? "bg-[#fde5e3] text-[#8d3636]" : assessment?.state === "WATCH" ? "bg-[#fff2d4] text-[#7d5411]" : "bg-[#daf0e8] text-[#21684f]"}`}><MapPinned size={22} /></div></div>{assessment && <div className="mt-6 space-y-4"><div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Coordinates</div><div className="mt-1 font-mono text-xs text-[#27445b]">{assessment.selectedLocation.lat.toFixed(5)}, {assessment.selectedLocation.lng.toFixed(5)}</div></div><RiskDetail label="Hazard" value={assessment.hazard} /><RiskDetail label="Warning severity" value={assessment.warningSeverity.toUpperCase()} tone={assessment.state === "ACTION" ? "red" : assessment.state === "WATCH" ? "amber" : "green"} /><RiskDetail label="Affected-zone relationship" value={assessment.affectedZoneRelationship} /><RiskDetail label="Distance to boundary" value={`${assessment.distanceToAffectedBoundaryKm} km`} /><RiskDetail label="Warning validity" value={`${formatTime(assessment.warningValidity.validFrom)} → ${formatTime(assessment.warningValidity.expiryTime)} IST`} /><div className="border-t border-[#e4ebee] pt-4"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Nearest relevant shelter</div><div className="mt-2 font-semibold text-[#27445b]">{assessment.nearestShelter.name}</div><div className="mt-1 text-xs leading-5 text-[#71818b]">{assessment.nearestShelter.address} · {assessment.nearestShelter.distanceKm} km · {assessment.nearestShelter.status}</div><div className="mt-2 text-[10px] text-[#84949d]">Shelter service: {shelter?.status ?? "checking"} · {shelter?.message ?? "availability lookup"}</div></div></div>}</Card>
        <Card className="p-5 md:p-6"><SectionTitle eyebrow="LIVE LOCATION SERVICES" title="Geocode & route" /><div className="space-y-3"><label className="block"><span className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Search a location</span><div className="mt-1.5 flex gap-2"><input value={locationQuery} onChange={event => setLocationQuery(event.target.value)} onKeyDown={event => { if (event.key === "Enter") findLocation(); }} className="sb-focus min-w-0 flex-1 rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm text-[#27445b]" /><button onClick={findLocation} disabled={geocode.isPending} className="sb-focus rounded-lg bg-[#0d3448] px-3 py-2 text-xs font-semibold text-white disabled:opacity-60">{geocode.isPending ? "…" : "Find"}</button></div></label><button onClick={calculateRoute} disabled={!assessment || route.isPending} className="sb-focus inline-flex w-full items-center justify-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf] disabled:opacity-60"><Navigation size={14} /> {route.isPending ? "Calculating route…" : "Calculate route to shelter"}</button>{routeResult && <div className="rounded-lg bg-[#f4f7f9] p-3 text-sm text-[#27445b]">{routeResult.status === "connected" ? <><span className="font-semibold">{routeResult.distanceKm} km</span> · approx. {routeResult.durationMinutes} min driving</> : <span>{routeResult.message ?? "Route not available"}</span>}<div className="mt-1 text-[10px] text-[#84949d]">Source: {routeResult.source}</div></div>}</div></Card>
        <Card className="p-5 md:p-6"><SectionTitle eyebrow="PROVENANCE & BOUNDARY" title="Read this result carefully" /><div className="space-y-3 text-sm leading-6 text-[#5c6d79]"><p>This assessment uses point-in-polygon intersection against the shared demonstration boundaries; the state is not a hardcoded display label.</p><p className="font-semibold text-[#7d5411]">{assessment?.disclaimer ?? "Simulated hazard boundaries for product demonstration only. This is not a real-time emergency prediction system."}</p><LiveIntegrationSummary integrations={integrations} /></div></Card><NextPhaseNotice text="Official GIS boundaries and shelter-capacity APIs remain configurable integrations; current public geocoding and routing responses show their own source and failure status." /></div></div>
  </Workspace>;
}
function LegendRow({ color, label, detail }: { color: string; label: string; detail: string }) { return <div className="flex items-center gap-3"><span className="h-3 w-3 rounded-full" style={{ background: color }} /><div><div className="text-sm font-semibold text-[#27445b]">{label}</div><div className="text-xs text-[#84949d]">{detail}</div></div></div>; }
function Note({ icon, text, tone }: { icon: React.ReactNode; text: string; tone: "red" | "amber" | "green" }) { const colors = { red: "bg-[#fde5e3] text-[#8d3636]", amber: "bg-[#fff2d4] text-[#7d5411]", green: "bg-[#daf0e8] text-[#21684f]" }; return <div className="flex items-center gap-3 rounded-lg bg-[#f4f7f9] p-3"><span className={`rounded-md p-2 ${colors[tone]}`}>{icon}</span><span className="text-sm font-medium text-[#27445b]">{text}</span></div>; }

function AlertField({ label, value, onChange }: { label: string; value?: string; onChange: (value: string) => void }) { return <label className="block"><span className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#84949d]">{label}</span><input value={value ?? ""} onChange={event => onChange(event.target.value)} className="sb-focus mt-1.5 w-full rounded-lg border border-[#cbd9df] bg-white px-3 py-2.5 text-sm text-[#27445b]" /></label>; }
function StructuredField({ label, value, tone }: { label: string; value: string; tone?: "red" | "amber" | "green" | "cyan" }) { return <div className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">{label}</div><div className="mt-1.5 flex items-center gap-2 text-sm font-semibold text-[#27445b]">{tone ? <StatusPill tone={tone}>{value}</StatusPill> : value}</div></div>; }
function ProvenancePanel({ warning }: { warning: { alertId: string; sourceLabel: string; sourceStatus: string; issuedAt: Date | string; validFrom: Date | string; validUntil: Date | string | null; warningText: string; recommendedPrecautions: string } }) { return <Card className="overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e4ebee] bg-[#f8fbfc] px-5 py-3 md:px-6"><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#2e8b91]" /><span className="font-mono text-[10px] font-semibold uppercase tracking-[.14em] text-[#27445b]">Source provenance · {warning.alertId}</span></div><StatusPill tone={warning.sourceStatus === "simulated" ? "amber" : "green"}>{warning.sourceStatus === "simulated" ? "Demo source" : warning.sourceStatus}</StatusPill></div><div className="grid gap-4 p-5 text-sm md:grid-cols-4 md:px-6"><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Source</div><div className="mt-1 font-semibold text-[#27445b]">{warning.sourceLabel}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Issued / valid</div><div className="mt-1 text-[#5c6d79]">{formatTime(warning.issuedAt)} / {formatTime(warning.validFrom)}–{formatTime(warning.validUntil)} IST</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Raw warning</div><div className="mt-1 text-[#5c6d79]">{warning.warningText}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Recommended precautions</div><div className="mt-1 text-[#5c6d79]">{warning.recommendedPrecautions}</div></div></div></Card>; }
function MapLegend({ color, label, detail }: { color: string; label: string; detail: string }) { return <div className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full" style={{ background: color }} /><div><div className="font-mono text-[9px] font-semibold tracking-[.11em] text-[#27445b]">{label}</div><div className="text-[10px] text-[#84949d]">{detail}</div></div></div>; }
function RiskDetail({ label, value, tone }: { label: string; value: string; tone?: "red" | "amber" | "green" }) { return <div className="flex items-start justify-between gap-4 border-b border-[#eef2f4] pb-3"><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">{label}</div>{tone ? <StatusPill tone={tone}>{value}</StatusPill> : <div className="max-w-[62%] text-right text-sm font-semibold leading-5 text-[#27445b]">{value}</div>}</div>; }
export function ActionPlansPage() {
  const { data, isLoading } = trpc.signalbridge.actionForge.useQuery();
  const [openId, setOpenId] = useState<string | null>("immediate-01");
  const categories = [["immediate", "IMMEDIATE ACTIONS", "What to do first", "red"], ["preparation", "PREPARATION ACTIONS", "Get ready for the next window", "amber"], ["avoidance", "AVOIDANCE ACTIONS", "Do not increase exposure", "red"], ["escalation", "ESCALATION ACTIONS", "When normal movement is not safe", "cyan"]] as const;
  return <Workspace><PageHeader eyebrow="ACTIONFORGE / EMERGENCY ACTION COMPILER" title="Emergency action plan" description="A prioritized, traceable plan compiled from the current warning, geographic relevance, trusted guidance, household profile, and accessibility context." action={<div className="flex items-center gap-2"><DemoLabel /><StatusPill tone="cyan">Traceable output</StatusPill></div>} />
    {isLoading || !data ? <div className="mt-7 grid gap-4"><LoadingCard /><LoadingCard /></div> : <div className="mt-7 grid gap-5 xl:grid-cols-[1.16fr_.84fr]"><Card className="overflow-hidden"><div className="border-b border-[#e4ebee] bg-[#f8fbfc] p-5 md:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#2e8b91]">COMPILED FOR {data.profile.displayName.toUpperCase()}</div><h2 className="mt-2 font-display text-2xl font-semibold tracking-[-.035em] text-[#0d1b2a]">Emergency Action Plan</h2><p className="mt-2 max-w-[680px] text-sm leading-6 text-[#5c6d79]">{data.warning.title} · {data.assessment.state} local relevance · valid until {formatTime(data.validity.validUntil)} IST</p></div><div className="rounded-xl bg-[#0d3448] px-4 py-3 text-right text-white"><div className="font-mono text-[9px] uppercase tracking-[.14em] text-[#9bd7d7]">Source status</div><div className="mt-1 text-sm font-semibold">{data.sourceStatus === "simulated" ? "Demo guidance" : data.sourceStatus}</div></div></div></div><div className="space-y-6 p-5 md:p-7">{categories.map(([category, title, subtitle, tone]) => { const actions = data.recommendations.filter(item => item.category === category); return <div key={category}><div className="mb-3 flex items-end justify-between gap-3"><div><div className={`font-mono text-[10px] font-semibold uppercase tracking-[.14em] ${tone === "red" ? "text-[#b64242]" : tone === "amber" ? "text-[#7d5411]" : "text-[#0d5960]"}`}>{title}</div><div className="mt-1 text-xs text-[#84949d]">{subtitle}</div></div><span className="font-mono text-[10px] text-[#84949d]">{actions.length} compiled</span></div><div className="space-y-3">{actions.map(action => <ActionForgeCard key={action.id} action={action} open={openId === action.id} onToggle={() => setOpenId(openId === action.id ? null : action.id)} />)}</div></div>; })}</div><div className="border-t border-[#e4ebee] bg-[#fff8e8] p-5 text-sm leading-6 text-[#7d5411] md:px-7"><span className="font-semibold">Important:</span> {data.disclaimer}</div></Card><div className="space-y-5"><Card className="p-5 md:p-6"><SectionTitle eyebrow="PLAN INPUTS" title="Why these actions appeared" /><div className="space-y-4"><InputTrace label="Emergency warning" value={data.warning.title} /><InputTrace label="Geographic relevance" value={`${data.assessment.state} · ${data.assessment.affectedZoneRelationship}`} /><InputTrace label="Trusted guidance" value={`${data.trustedGuidance.length} supplied precautions`} /><InputTrace label="Household context" value={`${data.profile.householdSize} people · ${data.profile.mobilityNeeds ?? "no mobility preference recorded"}`} /><InputTrace label="Accessibility" value={`${data.profile.preferredLanguage} · plain language`} /></div></Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="TRUSTMESH" title="Recommendation coverage" /><div className="grid grid-cols-2 gap-3"><Metric label="Evidence nodes" value={String(data.graph.nodes.length)} detail="linked records" tone="cyan" icon={<GitBranchIcon />} /><Metric label="Conflicts shown" value={String(data.graph.conflictCount)} detail="not auto-resolved" tone={data.graph.conflictCount ? "amber" : "green"} icon={<TriangleAlert size={18} />} /></div><Link href="/evidence" className="sb-focus mt-4 inline-flex items-center gap-2 text-xs font-semibold text-[#2e8b91] hover:underline">Inspect evidence graph <ArrowRight size={14} /></Link></Card><NextPhaseNotice text="Live official feeds, responder handoff, verified emergency contact numbers and human review remain explicit integration boundaries." /></div></div>}
  </Workspace>;
}

export function EvidencePage() {
  const { data: graph, isLoading } = trpc.signalbridge.evidenceGraph.useQuery();
  const { data: actions } = trpc.signalbridge.actionForge.useQuery();
  const { data: liveFeed } = trpc.signalbridge.officialFeed.useQuery();
  const chain = ["WARNING", "SOURCE", "GEOGRAPHIC RELEVANCE", "TRUSTED GUIDANCE", "COMMUNITY REPORT", "ACTION RECOMMENDATION"];
  const nodeFor = (type: string) => graph?.nodes.find(node => node.type === type) ?? graph?.nodes.find(node => node.type.includes(type));
  return <Workspace><PageHeader eyebrow="TRUSTMESH / EVIDENCE & UNCERTAINTY" title="Evidence center" description="Inspect the chain behind each recommendation. TrustMesh exposes source, relevance, confidence, timestamps, conflicts, and uncertainty without claiming AI authority." action={<div className="flex items-center gap-2"><DemoLabel /><StatusPill tone={graph?.conflictCount ? "amber" : "green"}>{graph?.conflictCount ?? 0} conflicts visible</StatusPill></div>} />
    {isLoading || !graph ? <div className="mt-7 grid gap-4"><LoadingCard /><LoadingCard /></div> : <><div className="mt-7 grid gap-5 xl:grid-cols-[1.18fr_.82fr]"><Card className="overflow-hidden"><div className="border-b border-[#e4ebee] p-5 md:p-6"><SectionTitle eyebrow="EVIDENCE GRAPH" title="Warning → action trace" /><p className="mt-2 text-sm leading-6 text-[#5c6d79]">Every arrow is a relationship, not a claim that one source overrides another.</p></div><div className="space-y-3 p-5 md:p-6">{chain.map((type, index) => { const node = nodeFor(type); return <div key={type} className="flex items-stretch gap-3"><div className="flex w-7 shrink-0 flex-col items-center"><div className={`flex h-7 w-7 items-center justify-center rounded-full text-[10px] font-bold ${node?.category === "conflicting" ? "bg-[#fff2d4] text-[#7d5411]" : "bg-[#d9f1f0] text-[#0d5960]"}`}>{String(index + 1).padStart(2, "0")}</div>{index < chain.length - 1 && <div className="my-1 w-px flex-1 bg-[#cbd9df]" />}</div><div className="min-w-0 flex-1 rounded-xl border border-[#e4ebee] bg-white p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#2e8b91]">{type}</div>{node && <EvidenceCategoryPill category={node.category} />}</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{node?.label ?? "Waiting for evidence"}</div>{node && <div className="mt-3 grid gap-2 text-xs text-[#71818b] sm:grid-cols-3"><span>Confidence <b className="text-[#27445b]">{node.confidence}%</b></span><span>Relevance <b className="text-[#27445b]">{node.relevance}%</b></span><span>{formatDate(node.timestamp)}</span></div>}{node && <div className="mt-3 rounded-lg bg-[#f4f7f9] p-3 text-xs leading-5 text-[#5c6d79]"><span className="font-semibold text-[#27445b]">Uncertainty:</span> {node.uncertainty}</div>}</div></div>; })}</div></Card><div className="space-y-5"><Card className="p-5 md:p-6"><SectionTitle eyebrow="CATEGORIES" title="Evidence labels" /><div className="space-y-3"><EvidenceLegend category="verified" detail="Official or corroborated source" /><EvidenceLegend category="supported" detail="Useful context with some limits" /><EvidenceLegend category="unverified" detail="Lead requiring review" /><EvidenceLegend category="conflicting" detail="Sources disagree; no auto-choice" /><EvidenceLegend category="unknown" detail="Missing or unconfigured evidence" /></div></Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="LIVE SOURCE STATUS" title="Official feed provenance" /><div className="flex items-start gap-3"><span className={`mt-1 h-2 w-2 rounded-full ${liveFeed?.verified ? "bg-[#2e8b70]" : "bg-[#d39124]"}`} /><div className="min-w-0 flex-1"><div className="text-sm font-semibold text-[#27445b]">{liveFeed?.provider ?? "SACHET / IMD adapter"}</div><div className="mt-1 text-xs leading-5 text-[#71818b]">{liveFeed?.message ?? "Checking configured official feed"}</div></div><StatusPill tone={liveFeed?.verified ? "green" : "amber"}>{liveFeed?.status ?? "checking"}</StatusPill></div></Card><NextPhaseNotice text={graph.disclaimer} /></div></div><div className="mt-5"><SectionTitle eyebrow="ACTION RECOMMENDATION EVIDENCE" title="Why this recommendation?" /><div className="grid gap-4 lg:grid-cols-2">{actions?.recommendations.map(action => <Card key={action.id} className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><EvidenceCategoryPill category={action.evidenceCategory} /><h2 className="mt-3 font-display text-lg font-semibold text-[#0d1b2a]">{action.action}</h2></div><span className="font-mono text-xs text-[#84949d]">{action.confidence}%</span></div><div className="mt-4 grid gap-3 text-sm leading-5 text-[#5c6d79]"><p><span className="font-semibold text-[#27445b]">Reason:</span> {action.reason}</p><p><span className="font-semibold text-[#27445b]">Supporting evidence:</span> {action.supportingEvidence}</p><p><span className="font-semibold text-[#27445b]">Source:</span> {action.source}</p><p><span className="font-semibold text-[#27445b]">Uncertainty:</span> {action.uncertainty}</p></div><Link href="/action-plans" className="sb-focus mt-4 inline-flex items-center gap-1.5 text-xs font-semibold text-[#2e8b91] hover:underline">Open in ActionForge <ArrowRight size={13} /></Link></Card>)}</div></div></>}
  </Workspace>;
}

function ActionForgeCard({ action, open, onToggle }: { action: { action: string; priority: string; reason: string; supportingEvidence: string; source: string; evidenceCategory: string; confidence: number; uncertainty: string }; open: boolean; onToggle: () => void }) { return <div className={`rounded-xl border p-4 transition ${action.priority === "now" ? "border-[#ead3d0] bg-[#fffafa]" : "border-[#e4ebee] bg-white"}`}><div className="flex gap-3"><div className={`mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg ${action.priority === "now" ? "bg-[#fde5e3] text-[#8d3636]" : "bg-[#d9f1f0] text-[#0d5960]"}`}><Check size={15} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><div><div className="flex flex-wrap items-center gap-2"><h3 className="font-semibold leading-5 text-[#27445b]">{action.action}</h3><StatusPill tone={priorityTone(action.priority)}>{action.priority}</StatusPill></div><div className="mt-2 text-sm leading-6 text-[#5c6d79]">{action.reason}</div></div><button onClick={onToggle} className="sb-focus inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-[#cbd9df] bg-white px-2.5 py-2 text-[11px] font-semibold text-[#27445b] hover:border-[#7fb8bf]"><Sparkles size={13} /> Why this action?</button></div><div className="mt-3 flex flex-wrap items-center gap-3 border-t border-[#e4ebee] pt-3 text-[10px] font-mono uppercase tracking-[.1em] text-[#84949d]"><span>{action.source}</span><span>{action.confidence}% confidence</span><EvidenceCategoryPill category={action.evidenceCategory} /></div>{open && <div className="mt-4 rounded-lg bg-[#f4f7f9] p-4 text-sm leading-6 text-[#5c6d79]"><div className="font-mono text-[9px] font-semibold uppercase tracking-[.13em] text-[#2e8b91]">SUPPORTING EVIDENCE</div><p className="mt-2"><span className="font-semibold text-[#27445b]">Evidence:</span> {action.supportingEvidence}</p><p className="mt-2"><span className="font-semibold text-[#27445b]">Uncertainty:</span> {action.uncertainty}</p></div>}</div></div></div>; }
function InputTrace({ label, value }: { label: string; value: string }) { return <div className="border-b border-[#eef2f4] pb-3"><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">{label}</div><div className="mt-1 text-sm font-semibold leading-5 text-[#27445b]">{value}</div></div>; }
function EvidenceCategoryPill({ category }: { category: string }) { const tone = category === "verified" ? "green" : category === "supported" ? "cyan" : category === "conflicting" ? "amber" : category === "unknown" ? "slate" : "red"; return <StatusPill tone={tone}>{category}</StatusPill>; }
function EvidenceLegend({ category, detail }: { category: string; detail: string }) { return <div className="flex items-center gap-3"><EvidenceCategoryPill category={category} /><span className="text-xs text-[#71818b]">{detail}</span></div>; }
function GitBranchIcon() { return <div className="relative h-[18px] w-[18px]"><span className="absolute left-0 top-1 h-2 w-2 rounded-full border-2 border-current" /><span className="absolute right-0 bottom-1 h-2 w-2 rounded-full border-2 border-current" /><span className="absolute left-[6px] top-[5px] h-2 w-[7px] border-l border-b border-current" /></div>; }
function LiveIntegrationSummary({ integrations }: { integrations?: { officialWarnings?: { verification: string }; geocoder?: { provider: string }; routing?: { provider: string }; shelters?: { verification: string } } }) { return <div className="mt-3 rounded-lg bg-[#f4f7f9] p-3 text-xs leading-5 text-[#71818b]"><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Service provenance</div><div className="mt-2 space-y-1"><div>Warnings: {integrations?.officialWarnings?.verification ?? "checking"}</div><div>Geocoder: {integrations?.geocoder?.provider ?? "checking"}</div><div>Routing: {integrations?.routing?.provider ?? "checking"}</div><div>Shelter capacity: {integrations?.shelters?.verification ?? "checking"}</div></div></div>; }
export function CitizenIntelligencePage() {
  const { data, isLoading } = trpc.signalbridge.crowdPulse.useQuery();
  const [filter, setFilter] = useState("all");
  const reports = data?.reports ?? [];
  const clusters = useMemo(() => data?.clusters.filter(cluster => filter === "all" || cluster.verificationStatus === filter) ?? [], [data, filter]);
  const statusTone = (status: string) => status === "SUPPORTED" ? "green" : status === "CONFLICTING" ? "amber" : status === "PENDING VERIFICATION" ? "cyan" : "slate";
  return <Workspace><PageHeader eyebrow="CROWDPULSE / CITIZEN INCIDENT INTELLIGENCE" title="Citizen intelligence" description="Group noisy community reports into local context without allowing citizen signals to become official warnings." action={<div className="flex items-center gap-2"><DemoLabel>Community data</DemoLabel><button onClick={() => toast.info("Report intake", { description: "The prototype is showing simulated reports; submissions remain a human-review workflow." })} className="sb-focus inline-flex items-center gap-2 rounded-lg bg-[#0d3448] px-3.5 py-2.5 text-xs font-semibold text-white hover:bg-[#174a60]"><MessageSquareWarning size={15} /> Report an incident</button></div>} />
    <div className="mt-7 flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-2">{[["all", "All clusters"], ["SUPPORTED", "Supported"], ["PENDING VERIFICATION", "Pending verification"], ["CONFLICTING", "Conflicting"]].map(([value, label]) => <button key={value} onClick={() => setFilter(value)} className={`sb-focus rounded-full px-3 py-1.5 text-xs font-semibold transition ${filter === value ? "bg-[#0d3448] text-white" : "border border-[#cbd9df] bg-white text-[#5c6d79] hover:border-[#7fb8bf]"}`}>{label}</button>)}</div><div className="flex items-center gap-2 rounded-full border border-[#e4d39e] bg-[#fff8e8] px-3 py-1.5 text-[10px] font-mono uppercase tracking-[.1em] text-[#7d5411]"><ShieldAlert size={13} /> Not an official warning feed</div></div>
    {isLoading || !data ? <div className="mt-5 grid gap-4 md:grid-cols-2"><LoadingCard /><LoadingCard /></div> : <><div className="mt-5 grid gap-4 md:grid-cols-3"><Metric label="Reports grouped" value={String(reports.length)} detail="Simulated community reports" tone="cyan" icon={<UsersRound size={18} />} /><Metric label="Incident clusters" value={String(data.clusters.length)} detail="Semantic + geographic grouping" tone="amber" icon={<GitBranchIcon />} /><Metric label="Needs review" value={String(data.clusters.filter(cluster => cluster.verificationStatus !== "SUPPORTED").length)} detail="Never promoted automatically" tone="red" icon={<TriangleAlert size={18} />} /></div><div className="mt-5 grid gap-5 lg:grid-cols-2">{clusters.map(cluster => <Card key={cluster.id} className="p-5 md:p-6"><div className="flex items-start justify-between gap-3"><div><div className="font-mono text-[9px] uppercase tracking-[.14em] text-[#2e8b91]">INCIDENT CLUSTER · {cluster.semanticSimilarity}% semantic similarity</div><h2 className="mt-2 font-display text-xl font-semibold leading-6 text-[#0d1b2a]">{cluster.title}</h2></div><StatusPill tone={statusTone(cluster.verificationStatus) as "green" | "amber" | "cyan" | "slate"}>{cluster.verificationStatus}</StatusPill></div><p className="mt-4 text-sm leading-6 text-[#5c6d79]">{cluster.representativeSummary}</p><div className="mt-5 grid gap-3 border-t border-[#e4ebee] pt-4 sm:grid-cols-3"><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Related reports</div><div className="mt-1 text-lg font-semibold text-[#27445b]">{cluster.reportCount}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Geographic spread</div><div className="mt-1 text-lg font-semibold text-[#27445b]">{cluster.geographicSpreadKm} km</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Latest report</div><div className="mt-1 text-sm font-semibold text-[#27445b]">{formatTime(cluster.latestReportTime)} IST</div></div></div><div className="mt-4 rounded-lg bg-[#f4f7f9] p-3 text-xs leading-5 text-[#5c6d79]"><span className="font-semibold text-[#27445b]">Safety boundary:</span> {cluster.disclaimer}</div></Card>)}</div><Card className="mt-5 overflow-hidden"><div className="border-b border-[#e4ebee] p-5 md:p-6"><SectionTitle eyebrow="REPORT LEDGER" title="Sample reports behind the clusters" /><p className="text-sm leading-6 text-[#5c6d79]">Each report keeps its original text, source, location, timestamp, category, and verification state. Grouping is assistive triage, not truth confirmation.</p></div><div className="divide-y divide-[#e4ebee]">{reports.map(report => <div key={report.id} className="grid gap-3 p-4 md:grid-cols-[1.4fr_.8fr_.7fr_.65fr] md:items-center md:px-6"><div><div className="text-sm font-semibold text-[#27445b]">{report.reportText}</div><div className="mt-1 flex items-center gap-1.5 text-xs text-[#71818b]"><MapPinned size={13} className="text-[#2e8b91]" /> {report.location.name}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">Category · source</div><div className="mt-1 text-xs font-semibold text-[#27445b]">{report.category} · {report.source}</div></div><div className="font-mono text-[10px] text-[#71818b]">{formatTime(report.timestamp)} IST</div><StatusPill tone={statusTone(report.verificationStatus) as "green" | "amber" | "cyan" | "slate"}>{report.verificationStatus}</StatusPill></div>)}</div></Card><div className="mt-5 rounded-xl border border-[#e4d39e] bg-[#fff8e8] p-4 text-sm leading-6 text-[#7d5411]"><span className="font-semibold">Official warning distinction:</span> {data.disclaimer}</div></>}
  </Workspace>;
}

export function AccessBridgePage() {
  const { data, isLoading } = trpc.signalbridge.accessBridge.useQuery();
  const [language, setLanguage] = useState<"English" | "Tamil" | "Simplified English">("English");
  const [largeText, setLargeText] = useState(false);
  const [simplified, setSimplified] = useState(false);
  const [screenReaderMode, setScreenReaderMode] = useState(false);
  const [voiceEnabled, setVoiceEnabled] = useState(false);
  const speak = (text: string) => { if (typeof window === "undefined" || !("speechSynthesis" in window)) { toast.info("Voice playback unavailable", { description: "This browser does not expose SpeechSynthesis." }); return; } window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = language === "Tamil" ? "ta-IN" : "en-IN"; utterance.rate = simplified ? 0.88 : 0.96; window.speechSynthesis.speak(utterance); setVoiceEnabled(true); };
  const textFor = (output: { standardEnglish: string; tamil: string; simplifiedEnglish: string }) => language === "Tamil" ? output.tamil : language === "Simplified English" || simplified ? output.simplifiedEnglish : output.standardEnglish;
  return <Workspace><PageHeader eyebrow="ACCESSBRIDGE / ADAPTIVE DELIVERY" title="Emergency accessibility" description="Keep the same ActionForge safety meaning while changing language, reading level, text size, screen-reader structure, and voice delivery." action={<div className="flex items-center gap-2 rounded-xl border-2 border-[#2e8b91] bg-[#d9f1f0] px-3 py-2 text-xs font-bold text-[#0d5960]"><Accessibility size={17} /> Emergency access mode</div>} />
    {isLoading || !data ? <div className="mt-7 grid gap-4 md:grid-cols-2"><LoadingCard /><LoadingCard /></div> : <div className={`mt-7 ${largeText ? "text-[118%]" : ""}`}><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Card className="p-5 md:p-6"><SectionTitle eyebrow="ACCESSIBILITY PREFERENCES" title="Choose how to receive the plan" /><div className="space-y-3"><label className="block"><span className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Language and reading mode</span><select value={language} onChange={event => setLanguage(event.target.value as typeof language)} className="sb-focus mt-1.5 w-full rounded-lg border border-[#cbd9df] bg-white px-3 py-3 text-sm font-semibold text-[#27445b]"><option>English</option><option>Tamil</option><option>Simplified English</option></select></label><AccessToggle label="Large-text emergency mode" detail="Increase plan text size for fast scanning." checked={largeText} onChange={setLargeText} icon={<Type size={17} />} /><AccessToggle label="Simplified emergency language" detail="Use shorter, direct English without changing safety meaning." checked={simplified} onChange={setSimplified} icon={<Languages size={17} />} /><AccessToggle label="Screen-reader structure" detail="Keep headings, live status, and action order explicit." checked={screenReaderMode} onChange={setScreenReaderMode} icon={<Accessibility size={17} />} /><AccessToggle label="Voice playback" detail="Use browser-native SpeechSynthesis; no paid voice API required." checked={voiceEnabled} onChange={() => { setVoiceEnabled(true); const first = data.outputs[0]; if (first) speak(textFor(first)); }} icon={<Volume2 size={17} />} /></div><div className="mt-5 rounded-lg bg-[#f4f7f9] p-3 text-xs leading-5 text-[#5c6d79]" aria-live="polite"><span className="font-semibold text-[#27445b]">Current output:</span> {language}{simplified ? " · simplified" : ""}{largeText ? " · large text" : ""}{screenReaderMode ? " · screen-reader structure" : ""}</div></Card><Card className="overflow-hidden"><div className="border-b border-[#e4ebee] bg-[#f8fbfc] p-5 md:p-6"><SectionTitle eyebrow="ACTIONFORGE / SAME SAFETY MEANING" title="Accessible action plan" action={<StatusPill tone="cyan">{data.outputs.length} actions</StatusPill>} /><p className="text-sm leading-6 text-[#5c6d79]">Switch the presentation format; the underlying priority, evidence, and uncertainty remain unchanged.</p></div><div className="space-y-3 p-5 md:p-6" aria-live={screenReaderMode ? "polite" : undefined}>{data.outputs.map(output => <article key={output.id} className="rounded-xl border border-[#e4ebee] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><StatusPill tone={priorityTone(output.priority)}>{output.priority}</StatusPill><span className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">{output.category}</span></div><h3 className={`mt-2 font-semibold leading-6 text-[#27445b] ${largeText ? "text-xl" : "text-base"}`}>{textFor(output)}</h3></div><button onClick={() => speak(textFor(output))} className="sb-focus inline-flex items-center gap-1.5 rounded-lg border border-[#cbd9df] bg-white px-2.5 py-2 text-[11px] font-semibold text-[#27445b] hover:border-[#7fb8bf]" aria-label={`Play ${output.category} action aloud`}><Volume2 size={14} /> Play</button></div><div className="mt-3 flex flex-wrap items-center gap-3 border-t border-[#e4ebee] pt-3 text-[10px] font-mono uppercase tracking-[.1em] text-[#84949d]"><span>{output.source}</span><span>{output.confidence}% confidence</span><EvidenceCategoryPill category={output.evidenceCategory} /></div><div className="mt-3 text-xs leading-5 text-[#71818b]">{output.safetyMeaning}</div></article>)}</div></Card></div><div className="mt-5 rounded-xl border border-[#e4d39e] bg-[#fff8e8] p-4 text-sm leading-6 text-[#7d5411]"><span className="font-semibold">AccessBridge safety rule:</span> {data.disclaimer}</div></div>}
  </Workspace>;
}

function AccessToggle({ label, detail, checked, onChange, icon }: { label: string; detail: string; checked: boolean; onChange: (checked: boolean) => void; icon: React.ReactNode }) { return <label className={`flex cursor-pointer items-start gap-3 rounded-xl border p-3 transition ${checked ? "border-[#2e8b91] bg-[#d9f1f0]" : "border-[#e4ebee] bg-white hover:border-[#a9cbd0]"}`}><span className="rounded-lg bg-[#f4f7f9] p-2 text-[#0d5960]">{icon}</span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold text-[#27445b]">{label}</span><span className="mt-1 block text-xs leading-5 text-[#71818b]">{detail}</span></span><input type="checkbox" checked={checked} onChange={event => onChange(event.target.checked)} className="mt-1 h-5 w-5 accent-[#0d5960]" /></label>; }

export function ProfilePage() { const { data, isLoading } = trpc.signalbridge.profile.useQuery(); return <Workspace><PageHeader eyebrow="PERSONAL / PROFILE" title="Emergency profile" description="The context SignalBridge uses to make safe actions more relevant to your household and access needs." action={<button onClick={() => toast.info("Profile editing", { description: "Profile persistence is coming in next integration phase." })} className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3.5 py-2.5 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]"><UserRound size={15} /> Edit profile</button>} /><div className="mt-7 grid gap-5 lg:grid-cols-[.9fr_1.1fr]"><Card className="p-5 md:p-7"><div className="flex items-center gap-4 border-b border-[#e4ebee] pb-6"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[#d9f1f0] font-display text-xl font-semibold text-[#0d5960]">AM</div><div><div className="font-display text-xl font-semibold text-[#0d1b2a]">{isLoading ? "Loading…" : data?.displayName}</div><div className="mt-1 flex items-center gap-1.5 text-sm text-[#71818b]"><MapPinned size={14} className="text-[#2e8b91]" /> {data?.homeArea}</div></div></div><div className="mt-6 space-y-5"><ProfileRow label="Household" value={`${data?.householdSize ?? "—"} people`} /><ProfileRow label="Access needs" value={data?.mobilityNeeds ?? "Not recorded"} /><ProfileRow label="Preferred language" value={data?.preferredLanguage ?? "English"} /><ProfileRow label="Emergency contact" value={data?.emergencyContact ?? "Not recorded"} icon={<PhoneCall size={14} />} /></div></Card><div className="space-y-5"><Card className="p-5 md:p-7"><SectionTitle eyebrow="WHY IT MATTERS" title="Personalization without guesswork" /><div className="space-y-4"><Reason icon={<Navigation size={17} />} title="Route context" detail="Step-free route preferences can shape which actions appear first." /><Reason icon={<UsersRound size={17} />} title="Household context" detail="The plan can account for the number of people who need to move together." /><Reason icon={<Languages size={17} />} title="Accessible delivery" detail="AccessBridge provides English, Tamil, simplified English, large text, screen-reader structure, and browser voice playback for the same plan." /></div></Card><NextPhaseNotice text="Profile editing, verified contact workflows and additional accessibility preferences are coming in next integration phase." /></div></div></Workspace>; }
function ProfileRow({ label, value, icon }: { label: string; value: string; icon?: React.ReactNode }) { return <div className="flex items-start justify-between gap-4"><div className="font-mono text-[10px] uppercase tracking-[.13em] text-[#84949d]">{label}</div><div className="flex max-w-[58%] items-center gap-1.5 text-right text-sm font-semibold text-[#27445b]">{icon}{value}</div></div>; }
function Reason({ icon, title, detail }: { icon: React.ReactNode; title: string; detail: string }) { return <div className="flex gap-3"><span className="rounded-lg bg-[#e8eef4] p-2 text-[#27445b]">{icon}</span><div><div className="text-sm font-semibold text-[#27445b]">{title}</div><div className="mt-1 text-xs leading-5 text-[#71818b]">{detail}</div></div></div>; }

export function SafetyPage() {
  const { data, isLoading } = trpc.signalbridge.safeLoop.useQuery();
  const utils = trpc.useUtils();
  const updateStatus = trpc.signalbridge.updateSafeLoop.useMutation({ onSuccess: () => { void utils.signalbridge.safeLoop.invalidate(); toast.success("SafeLoop status updated"); } });
  const state = data?.currentStatus ?? "ACTION PENDING";
  const isSafe = state === "SAFE";
  const isHelp = state === "ASSISTANCE NEEDED";
  const tone = state === "SAFE" ? "green" : state === "ASSISTANCE NEEDED" ? "red" : state === "ACTION PENDING" ? "amber" : "cyan";
  return <Workspace><PageHeader eyebrow="SAFELOOP / CLOSED-LOOP STATUS" title="Safety status" description="After receiving an ActionForge plan, record where you are in the response loop. SafeLoop stores a status and timestamp for this demo monitoring window." action={<DemoLabel>Prototype status</DemoLabel>} /><div className="mt-7 grid gap-5 lg:grid-cols-[1.05fr_.95fr]"><Card className={`overflow-hidden ${isSafe ? "border-[#c7e1d6]" : isHelp ? "border-[#ead3d0]" : "border-[#ead9ae]"}`}><div className={`p-6 md:p-8 ${isSafe ? "bg-[#f5fbf8]" : isHelp ? "bg-[#fffafa]" : "bg-[#fffaf0]"}`}><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><div className={`flex h-12 w-12 items-center justify-center rounded-2xl ${isSafe ? "bg-[#daf0e8] text-[#21684f]" : isHelp ? "bg-[#fde5e3] text-[#8d3636]" : "bg-[#fff2d4] text-[#7d5411]"}`}>{isSafe ? <CheckCircle2 size={24} /> : isHelp ? <PhoneCall size={24} /> : <ShieldAlert size={24} />}</div><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#84949d]">Current safety state</div><div className="mt-1 font-display text-2xl font-semibold text-[#0d1b2a]">{state}</div></div></div><StatusPill tone={tone as "green" | "red" | "amber" | "cyan"}>{state}</StatusPill></div><p className="mt-6 max-w-[620px] text-sm leading-6 text-[#5c6d79]">{isLoading ? "Loading SafeLoop status…" : isSafe ? "Your status is marked safe for this monitoring window." : isHelp ? "Assistance needed is recorded for this demo; no responder is automatically dispatched." : "Choose the status that best reflects your current response to the ActionForge plan."}</p><div className="mt-6 grid gap-2 sm:grid-cols-2">{["ACTION PENDING", "PREPARING", "EVACUATING", "SAFE", "ASSISTANCE NEEDED"].map(option => <button key={option} onClick={() => updateStatus.mutate({ status: option as typeof state })} disabled={updateStatus.isPending} className={`sb-focus flex items-center justify-between rounded-lg border px-3 py-3 text-left text-xs font-semibold transition ${state === option ? "border-[#2e8b91] bg-[#d9f1f0] text-[#0d5960]" : "border-[#d8e1e8] bg-white text-[#5c6d79] hover:border-[#7fb8bf]"}`}><span>{option}</span>{state === option && <Check size={15} />}</button>)}</div></div><div className="grid gap-4 border-t border-[#e4ebee] p-6 sm:grid-cols-2 md:p-8"><div><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Status timestamp</div><div className="mt-2 text-sm font-semibold text-[#27445b]">{data ? `${formatDate(data.updatedAt)} · ${formatTime(data.updatedAt)} IST` : "—"}</div></div><div><div className="font-mono text-[9px] uppercase tracking-[.13em] text-[#84949d]">Status storage</div><div className="mt-2 flex items-center gap-1.5 text-sm font-semibold text-[#2e8b70]"><CheckCircle2 size={14} /> Prototype session store</div></div></div></Card><Card className="p-5 md:p-6"><SectionTitle eyebrow="SAFELOOP TIMELINE" title="Closed-loop activity" /><div className="space-y-5">{(data?.timeline ?? []).map((event, index) => <div key={event.id} className="relative flex gap-3">{index < (data?.timeline.length ?? 0) - 1 && <div className="absolute left-[13px] top-8 h-[calc(100%+10px)] w-px bg-[#d8e1e8]" />}<div className="z-10 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[#d9f1f0] text-[#0d5960]"><Check size={14} /></div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-[9px] uppercase tracking-[.12em] text-[#2e8b91]">{event.type}</span>{event.status && <StatusPill tone={event.status === "SAFE" ? "green" : event.status === "ASSISTANCE NEEDED" ? "red" : "amber"}>{event.status}</StatusPill>}</div><div className="mt-1 text-sm font-semibold text-[#27445b]">{event.label}</div><div className="mt-1 text-xs leading-5 text-[#71818b]">{event.detail}</div><div className="mt-1 font-mono text-[10px] text-[#84949d]">{formatDate(event.timestamp)} · {formatTime(event.timestamp)} IST</div></div></div>)}</div><div className="mt-6 rounded-lg border border-[#e4d39e] bg-[#fff8e8] p-3 text-xs leading-5 text-[#7d5411]"><span className="font-semibold">Prototype boundary:</span> {data?.disclaimer ?? "SafeLoop does not automatically dispatch responders."}</div></Card></div></Workspace>;
}

function TimelineStep({ number, title, detail, done }: { number: string; title: string; detail: string; done?: boolean }) { return <div className="flex gap-3"><div className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full font-mono text-[10px] font-semibold ${done ? "bg-[#daf0e8] text-[#21684f]" : "bg-[#e8eef4] text-[#71818b]"}`}>{done ? <Check size={14} /> : number}</div><div><div className="text-sm font-semibold text-[#27445b]">{title}</div><div className="mt-1 text-xs leading-5 text-[#84949d]">{detail}</div></div></div>; }

export function OfflinePage() {
  const { data, isLoading } = trpc.signalbridge.resilienceVault.useQuery();
  const [offline, setOffline] = useState(() => typeof window !== "undefined" && localStorage.getItem("signalbridge:connectivity") === "offline");
  const [cachedBundle, setCachedBundle] = useState<typeof data>();
  useEffect(() => { const stored = typeof window !== "undefined" ? localStorage.getItem("signalbridge:resilience-vault") : null; if (stored) { try { setCachedBundle(JSON.parse(stored)); } catch { /* ignore malformed local cache */ } } }, []);
  useEffect(() => { if (data && typeof window !== "undefined") { localStorage.setItem("signalbridge:resilience-vault", JSON.stringify(data)); setCachedBundle(data); } }, [data]);
  const setConnectivity = (nextOffline: boolean) => { setOffline(nextOffline); if (typeof window !== "undefined") { localStorage.setItem("signalbridge:connectivity", nextOffline ? "offline" : "online"); window.dispatchEvent(new CustomEvent("signalbridge:connectivity", { detail: { offline: nextOffline } })); } toast.info(nextOffline ? "Offline emergency mode enabled" : "Simulated connectivity restored", { description: nextOffline ? "Using last synchronized emergency information." : "Live-connected demo shell restored." }); };
  const bundle = data ?? cachedBundle;
  const downloadCard = () => { if (!bundle) return; const content = ["SIGNALBRIDGE · RESILIENCEVAULT", "OFFLINE EMERGENCY MODE", `LAST SYNCHRONIZED: ${formatDate(bundle.lastSynchronizedAt)} · ${formatTime(bundle.lastSynchronizedAt)} IST`, "", ...bundle.essentialInstructions.map((action, index) => `${index + 1}. ${action.text}`), "", "TAMIL ACTION CARDS", ...bundle.tamilActionCards.map(action => `${action.category}: ${action.text}`), "", "EMERGENCY CONTACTS", ...bundle.emergencyContacts.map(contact => `${contact.name}: ${contact.number}`), "", "Cached information is not live. This prototype does not dispatch responders."]; const blob = new Blob([content.join("\n")], { type: "text/plain" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "signalbridge-resilience-vault.txt"; anchor.click(); URL.revokeObjectURL(url); toast.success("ResilienceVault card downloaded"); };
  return <Workspace><PageHeader eyebrow="RESILIENCEVAULT / OFFLINE" title="Offline emergency mode" description="Keep the latest verified demo warning, essential instructions, Tamil action cards, contacts, shelter information, and map context available when simulated connectivity is disabled." action={<div className="flex flex-wrap gap-2"><button onClick={() => setConnectivity(!offline)} className={`sb-focus inline-flex items-center gap-2 rounded-lg px-3.5 py-2.5 text-xs font-semibold ${offline ? "bg-[#b64242] text-white" : "bg-[#0d3448] text-white"}`}>{offline ? <WifiOff size={15} /> : <Wifi size={15} />}{offline ? "Restore simulated connection" : "Simulate connection loss"}</button><button onClick={downloadCard} disabled={!bundle} className="sb-focus inline-flex items-center gap-2 rounded-lg border border-[#cbd9df] bg-white px-3.5 py-2.5 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf] disabled:opacity-50"><Download size={15} /> Download vault</button></div>} /><div className={`mt-7 rounded-xl border-2 p-4 ${offline ? "border-[#b64242] bg-[#fff4f3]" : "border-[#2e8b91] bg-[#ecf8f7]"}`}><div className="flex flex-wrap items-center gap-3"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${offline ? "bg-[#fde5e3] text-[#8d3636]" : "bg-[#d9f1f0] text-[#0d5960]"}`}>{offline ? <WifiOff size={21} /> : <Wifi size={21} />}</div><div><div className={`font-mono text-[10px] font-bold uppercase tracking-[.16em] ${offline ? "text-[#8d3636]" : "text-[#0d5960]"}`}>{offline ? "OFFLINE EMERGENCY MODE" : "CONNECTED DEMO MODE"}</div><div className="mt-1 text-sm font-semibold text-[#27445b]">{offline ? "Using last synchronized emergency information" : "Demo connectivity available; cached vault remains ready"}</div></div><div className="ml-auto"><StatusPill tone={offline ? "red" : "green"}>{offline ? "Not live" : "Connected"}</StatusPill></div></div>{bundle && <div className="mt-3 border-t border-current/10 pt-3 text-xs text-[#5c6d79]">Last synchronization: <span className="font-mono font-semibold text-[#27445b]">{formatDate(bundle.lastSynchronizedAt)} · {formatTime(bundle.lastSynchronizedAt)} IST</span> · {bundle.syncStatus}</div>}</div>{isLoading || !bundle ? <div className="mt-5 grid gap-4 md:grid-cols-2"><LoadingCard /><LoadingCard /></div> : <><div className="mt-5 grid gap-5 lg:grid-cols-[.88fr_1.12fr]"><Card className="p-5 md:p-7"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#d9f1f0] p-3 text-[#0d5960]"><WifiOff size={22} /></div><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#2e8b91]">Vault contents</div><div className="mt-1 font-display text-xl font-semibold text-[#0d1b2a]">Latest verified demo warning</div></div></div><div className="mt-6 rounded-lg border border-[#e4ebee] p-4"><div className="flex flex-wrap items-center gap-2"><StatusPill tone="red">{bundle.warning.severity}</StatusPill><span className="font-mono text-[10px] text-[#84949d]">{bundle.warning.alertId}</span><DemoLabel>Cached / simulated</DemoLabel></div><div className="mt-3 text-lg font-semibold text-[#27445b]">{bundle.warning.hazard} · {bundle.warning.affectedArea}</div><p className="mt-2 text-sm leading-6 text-[#5c6d79]">{bundle.warning.text}</p><div className="mt-3 text-xs text-[#71818b]">Source: {bundle.warning.source} · validity ends {bundle.warning.expiryTime}</div></div><div className="mt-5 space-y-3">{bundle.essentialInstructions.map((action, index) => <div key={action.category} className="flex gap-3 rounded-lg border border-[#e4ebee] p-3"><span className="font-mono text-xs text-[#2e8b91]">{String(index + 1).padStart(2, "0")}</span><div><div className="text-sm font-semibold text-[#27445b]">{action.text}</div><div className="mt-1 text-[10px] font-mono uppercase tracking-[.1em] text-[#84949d]">{action.category} · {action.source}</div></div></div>)}</div></Card><Card className="overflow-hidden"><div className="border-b border-[#e4ebee] px-5 py-4 md:px-6"><SectionTitle eyebrow="RESILIENCEVAULT / AVAILABLE OFFLINE" title="Field-ready emergency information" action={<StatusPill tone="cyan">{bundle.tamilActionCards.length} Tamil cards</StatusPill>} /></div><div className="grid gap-px bg-[#e4ebee] sm:grid-cols-2"><div className="bg-white p-5"><div className="flex items-center gap-2 text-sm font-semibold text-[#27445b]"><Languages size={16} className="text-[#2e8b91]" /> Tamil action cards</div><div className="mt-3 space-y-3">{bundle.tamilActionCards.map(action => <div key={action.category} className="rounded-lg bg-[#f4f7f9] p-3"><div className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84949d]">{action.category}</div><div className="mt-1 text-sm leading-6 text-[#27445b]">{action.text}</div></div>)}</div></div><div className="bg-white p-5"><div className="flex items-center gap-2 text-sm font-semibold text-[#27445b]"><PhoneCall size={16} className="text-[#2e8b91]" /> Emergency contacts</div><div className="mt-3 space-y-3">{bundle.emergencyContacts.map(contact => <div key={contact.name} className="rounded-lg bg-[#f4f7f9] p-3"><div className="text-sm font-semibold text-[#27445b]">{contact.name}</div><div className="mt-1 font-mono text-sm text-[#0d5960]">{contact.number}</div><div className="mt-1 text-xs leading-5 text-[#71818b]">{contact.note}</div></div>)}</div></div><div className="bg-white p-5 sm:col-span-2"><div className="flex items-center gap-2 text-sm font-semibold text-[#27445b]"><MapPinned size={16} className="text-[#2e8b91]" /> Shelter and map information</div><div className="mt-3 grid gap-3 md:grid-cols-2">{bundle.shelters.map(shelter => <div key={shelter.name} className="rounded-lg border border-[#e4ebee] p-3"><div className="flex items-center justify-between gap-2"><div className="text-sm font-semibold text-[#27445b]">{shelter.name}</div><StatusPill tone="green">{shelter.status}</StatusPill></div><div className="mt-1 text-xs text-[#71818b]">{shelter.address}</div></div>)}</div><div className="mt-3 rounded-lg bg-[#fff8e8] p-3 text-xs leading-5 text-[#7d5411]">{bundle.mapInformation.disclaimer}</div></div></div></Card></div><div className="mt-5 rounded-xl border border-[#e4d39e] bg-[#fff8e8] p-4 text-sm leading-6 text-[#7d5411]"><span className="font-semibold">Cached-content rule:</span> {bundle.disclaimer}</div></>}</Workspace>;
}

function OfflineRow({ number, title }: { number: string; title: string }) { return <div className="flex items-center gap-3 rounded-lg border border-[#e4ebee] p-3"><span className="font-mono text-xs text-[#2e8b91]">{number}</span><span className="text-sm font-semibold text-[#27445b]">{title}</span><Check size={15} className="ml-auto text-[#2e8b70]" /></div>; }

export function SettingsPage() { const [notifications, setNotifications] = useState(true); const [reducedMotion, setReducedMotion] = useState(false); const [language, setLanguage] = useState("English"); return <Workspace><PageHeader eyebrow="SYSTEM / PREFERENCES" title="Settings" description="Adjust the foundation experience. Some integrations are intentionally staged for a later phase." action={<StatusPill tone="slate">Foundation v0.1</StatusPill>} /><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_.7fr]"><Card className="divide-y divide-[#e4ebee]"><SettingRow icon={<Bell size={17} />} title="Emergency alert notifications" description="Keep current warning updates visible in this workspace." control={<button onClick={() => setNotifications(!notifications)} className={`sb-focus relative h-6 w-11 rounded-full transition ${notifications ? "bg-[#2e8b91]" : "bg-[#cbd9df]"}`} aria-label="Toggle emergency alert notifications"><span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow transition ${notifications ? "left-6" : "left-1"}`} /></button>} /><SettingRow icon={<Languages size={17} />} title="Preferred language" description="Used for future accessible action-plan output." control={<select value={language} onChange={event => setLanguage(event.target.value)} className="sb-focus rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b]"><option>English</option><option>Tamil (next phase)</option></select>} /><SettingRow icon={<SlidersHorizontal size={17} />} title="Reduced motion" description="Respect a lower-motion presentation for interface transitions." control={<button onClick={() => setReducedMotion(!reducedMotion)} className={`sb-focus relative h-6 w-11 rounded-full transition ${reducedMotion ? "bg-[#2e8b91]" : "bg-[#cbd9df]"}`} aria-label="Toggle reduced motion"><span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow transition ${reducedMotion ? "left-6" : "left-1"}`} /></button>} /><SettingRow icon={<Wifi size={17} />} title="Connectivity diagnostics" description="Last sync 06:32 IST · Stable in this demo session." control={<button onClick={() => toast.success("Connection check complete", { description: "SignalBridge demo connection is stable." })} className="sb-focus inline-flex items-center gap-1.5 rounded-lg border border-[#cbd9df] bg-white px-3 py-2 text-xs font-semibold text-[#27445b] hover:border-[#7fb8bf]"><RefreshCw size={13} /> Check</button>} /></Card><div className="space-y-5"><Card className="p-5 md:p-6"><SectionTitle eyebrow="PRODUCT BOUNDARY" title="What is not connected yet" /><div className="space-y-3 text-sm leading-6 text-[#5c6d79]"><div className="flex gap-2"><span className="text-[#dd9c30]">—</span><span>OpenRouter or any external AI provider</span></div><div className="flex gap-2"><span className="text-[#dd9c30]">—</span><span>Live government alert feeds</span></div><div className="flex gap-2"><span className="text-[#dd9c30]">—</span><span>Responder and contact escalation</span></div></div></Card><NextPhaseNotice /></div></div></Workspace>; }
function SettingRow({ icon, title, description, control }: { icon: React.ReactNode; title: string; description: string; control: React.ReactNode }) { return <div className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between md:p-6"><div className="flex gap-3"><span className="rounded-lg bg-[#e8eef4] p-2 text-[#27445b]">{icon}</span><div><div className="text-sm font-semibold text-[#27445b]">{title}</div><div className="mt-1 max-w-[530px] text-xs leading-5 text-[#84949d]">{description}</div></div></div>{control}</div>; }
